(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11;
  const w2x = Math.sin(w1y*0.03+t*0.4)*8 + Math.cos(w1x*0.025-t*0.35)*6;
  const w2y = Math.cos(w1x*0.028-t*0.38)*7 + Math.sin(w1y*0.022+t*0.45)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 5],
    [80+Math.sin(t*0.45+1.5)*70, 40+Math.cos(t*0.65+0.5)*55, 0.1, 2.1, 6],
    [400+Math.cos(t*0.55+3)*85, 200+Math.sin(t*0.75+2)*65, 0.075, 1.8, 7]
  ];
  let aS = 0, iS = 0, cS = 0;
  for (const [sX, sY, f, sp, id] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const phase = id * 0.785;
    aS += Math.sin(d*f - t*sp + phase);
    iS += Math.sin(d*f*0.6 + t*sp*0.55 + phase + 1.2);
    cS += Math.cos(d*f*1.3 - t*sp*0.8 + phase*0.5) * 0.4;
  }
  const n = src.length, act = aS/n, inh = iS/n, cross = cS/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*0.95))/2
