  const kill = 0.062 - cross*0.005;
  const reaction = Math.tanh((act - inh*0.65 + (feed-kill)*8 + spiral + bg*0.25 + lap*0.15)*2.0);
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.12 + Math.sin((sx*2+sy)*0.25+t*4)*0.08;
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.09+t)*0.5)*1.6)*0.25;
  const blend = reaction*0.65 + cell*0.2 + micro*0.15, v = blend*0.5+0.5;
  const vig = 1.0 - Math.pow(dist/280, 2.5)*0.35;
  const pal = [
    [6,14,52],[12,42,88],[18,82,118],[28,128,132],[50,158,128],
    [130,172,85],[195,178,60],[215,145,65],[205,105,72],[175,68,72],
    [120,38,68],[65,22,62],[30,15,55],[6,14,52]
