    Math.min(255, Math.max(0, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f + glow*25)*lum*edge))|0,
    Math.min(255, Math.max(0, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f + glow*15)*lum*edge))|0
  ];
}
